<script lang="ts">
  import type { MediaScan } from './types';
  export let path = ''; export let result: MediaScan | null = null; export let notice = ''; export let output = ''; export let selected = ''; export let choose: () => void; export let scan: () => void; export let exportList: () => void;
</script>
<section class="jobs-panel page" aria-labelledby="playlists-title"><header><div><p class="eyebrow">PLAYLISTS</p><h1 id="playlists-title">Playlists</h1><p class="lede">Read ordinary `.m3u` files without changing your library.</p></div></header><section class="settings-card"><div class="picker-row"><input bind:value={path} placeholder="/Users/me/Music"/><button class="picker" on:click={choose}>Choose</button><button class="primary" on:click={scan}>Scan</button></div><p class="notice" role="status">{notice}</p></section>{#if result}<section class="core-list">{#each result.playlists as playlist}<article><div class="core-icon">♪</div><div><h3>{playlist.name}</h3><p>{playlist.tracks} tracks</p></div><span class="chip capable">Imported</span><button class="quiet" on:click={() => selected = playlist.name}>Select</button></article>{/each}</section><section class="settings-card"><h2>Export playlist</h2><div class="picker-row"><input bind:value={output} placeholder="/Users/me/Desktop/playlist.m3u"/><button class="primary" disabled={!selected || !output} on:click={exportList}>Export</button></div><p class="notice">{selected ? `Selected: ${selected}` : 'Select a playlist first.'}</p></section>{#if result.warnings.length}<section class="settings-card"><h2>Import warnings</h2><ul>{#each result.warnings as warning}<li>{warning}</li>{/each}</ul></section>{/if}{:else}<section class="empty"><div class="empty-art">♫</div><h2>No playlists scanned</h2><p>Choose a media folder to inspect its playlists.</p></section>{/if}</section>
